    Transform rule: For each column, if there's a contiguous block of trigger values
    followed immediately by target values, that entire trigger block becomes target.
    Otherwise, each trigger value following background becomes background.
    """
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    for c in range(cols):
        # Scan column for patterns
        r = 0
        while r < rows:
            # Skip non-trigger
            if grid[r][c] != trigger_val:
                r += 1
                continue

            # Found start of trigger block
            start = r
            while r < rows and grid[r][c] == trigger_val:
                r += 1
            end = r - 1

            # After trigger block, what do we have?
            if r < rows:
                val_after = grid[r][c]
                if val_after == target_val:
                    # Good! Trigger block is followed by target
                    for sr in range(start, end + 1):
                        result[sr][c] = target_val
                else:
